<?php
namespace App\Models\Sla; use App\Models\Concerns\HasPublicUuid; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo;
class SlaInstance extends Model {use HasPublicUuid;protected $fillable=['sla_policy_id','resource_type','resource_id','priority','state','started_at','first_response_due_at','next_response_due_at','resolution_due_at','first_response_fulfilled_at','resolution_fulfilled_at','paused_at','paused_seconds','breached_at'];protected function casts():array{return ['started_at'=>'datetime','first_response_due_at'=>'datetime','next_response_due_at'=>'datetime','resolution_due_at'=>'datetime','first_response_fulfilled_at'=>'datetime','resolution_fulfilled_at'=>'datetime','paused_at'=>'datetime','breached_at'=>'datetime'];}public function policy():BelongsTo{return $this->belongsTo(SlaPolicy::class,'sla_policy_id');}}
